// Data validation set, changed and cleared in the editor: the dialog (keyboard,
// focus, Escape), a rule of every kind and what it does afterwards (a refused
// value, the list of a cell, the message beside it), undo and redo, save and
// reopen, a read-only view, the Turkish way of typing, and a narrow screen.
// Every workbook is generated by code and kept within columns A to D of the
// first rows, so that a phone shows it as well.
import type { Page } from '@playwright/test';
import { buildXlsx, worksheetXml } from '../test/fixtures';
import { expect, test } from './helpers';

const num = (ref: string, value: number) => `<c r="${ref}"><v>${value}</v></c>`;
const str = (ref: string, text: string) => `<c r="${ref}" t="inlineStr"><is><t>${text}</t></is></c>`;
const dv = (attrs: string, inner = '') => `<dataValidation ${attrs}>${inner}</dataValidation>`;

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/** "Data": A2:A9 whole numbers 1 to 10 with messages; B2:B3 a list. "Lists": Red, Green, Blue. */
const workbook = once(() =>
  buildXlsx({
    sheets: [
      {
        name: 'Data',
        xml: worksheetXml(
          `<sheetData><row r="1">${str('A1', 'Qty')}${str('B1', 'Answer')}</row><row r="2">${num('A2', 3)}</row></sheetData>` +
            '<dataValidations count="2">' +
            dv('type="whole" allowBlank="1" showInputMessage="1" showErrorMessage="1" errorStyle="warning" errorTitle="Quantity" error="Enter 1 to 10" promptTitle="Qty" prompt="A whole number" sqref="A2:A9"', '<formula1>1</formula1><formula2>10</formula2>') +
            dv('type="list" allowBlank="1" showErrorMessage="1" sqref="B2:B3"', '<formula1>"Yes,No"</formula1>') +
            '</dataValidations>',
        ),
      },
      { name: 'Lists', xml: worksheetXml(`<sheetData><row r="1">${str('A1', 'Red')}</row><row r="2">${str('A2', 'Green')}</row><row r="3">${str('A3', 'Blue')}</row></sheetData>`) },
    ],
  }),
);

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}): Promise<void> {
  await page.goto('/e2e/pages/editor.html');
  await page.waitForFunction(() => typeof (window as any).__mountEditor === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountEditor(data, options, 'host');
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
}

const select = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const view = (window as any).__editor.view;
    view.select(api.parseRange(ref));
    view.focus();
  }, ref);

/** Types into the active cell and presses Enter. */
async function typeIn(page: Page, ref: string, text: string): Promise<void> {
  await select(page, ref);
  await page.keyboard.type(text);
  await page.keyboard.press('Enter');
}

const cellValue = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const at = api.parseCellRef(ref);
    const found = api.getCell((window as any).__editor.view.workbook.sheets[(window as any).__editor.view.activeSheet], at.row, at.col);
    return found ? found.value : null;
  }, ref);

/** The rule of a cell as the view applies it: "ranges|type|operator|formula1|formula2", or null. */
const ruleAt = (page: Page, ref: string) =>
  page.evaluate((ref) => {
    const api = (window as any).BymOffice;
    const at = api.parseCellRef(ref);
    const rule = (window as any).__editor.view.validationAt(at.row, at.col);
    return rule ? `${rule.ranges.map(api.rangeName).join(' ')}|${rule.type}|${rule.operator}|${rule.formula1 ?? ''}|${rule.formula2 ?? ''}` : null;
  }, ref);

const open = (page: Page) => page.evaluate(() => (window as any).__editor.view.openValidationDialog() as boolean);
const dialog = (page: Page) => page.locator('#host [data-bym-dialog="validation"]');
const field = (page: Page, name: string) => dialog(page).locator(`[data-bym-field="${name}"]`);
const action = (page: Page, name: string) => dialog(page).locator(`[data-bym-action="${name}"]`);
const alert = (page: Page) => dialog(page).locator('[role="alert"]');
const editing = (page: Page) => page.evaluate(() => (window as any).__editor.view.isEditing as boolean);
const message = (page: Page) => page.locator('#host .bym-status-message');
const focusedField = (page: Page) => page.evaluate(() => (document.activeElement ? document.activeElement.getAttribute('data-bym-field') || document.activeElement.getAttribute('data-bym-action') || document.activeElement.className : ''));
const gridHasFocus = (page: Page) => page.evaluate(() => !!document.activeElement && document.activeElement.classList.contains('bym-input'));
const changes = (page: Page) => page.evaluate(() => (window as any).__events.filter((event: { type: string }) => event.type === 'change').length as number);

/** Fills the dialog: selects and check boxes by value, text fields by typing over what they hold. */
async function fill(page: Page, values: Record<string, string | boolean>): Promise<void> {
  for (const [name, value] of Object.entries(values)) {
    const control = field(page, name);
    if (typeof value === 'boolean') await control.setChecked(value);
    else if ((await control.evaluate((el) => el.tagName)) === 'SELECT') await control.selectOption(value);
    else await control.fill(value);
  }
}

/** Opens the dialog for a range, fills it and presses OK. */
async function setRule(page: Page, ref: string, values: Record<string, string | boolean>): Promise<void> {
  await select(page, ref);
  expect(await open(page)).toBe(true);
  await fill(page, values);
  await action(page, 'ok').click();
}

test.describe('editing data validation', () => {
  test('the dialog is modal: the focus starts in it and stays in it, Enter applies and Escape closes, and the focus goes back to the cells', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'C2:C4');
    expect(await open(page)).toBe(true);
    await expect(dialog(page)).toBeVisible();
    await expect(dialog(page)).toHaveAttribute('role', 'dialog');
    await expect(dialog(page)).toHaveAttribute('aria-modal', 'true');
    const labelled = await dialog(page).getAttribute('aria-labelledby');
    await expect(page.locator(`#${labelled}`)).toHaveText('Data validation');
    expect(await focusedField(page)).toBe('type');
    // "Any value" has nothing to state: no operator and no value are shown.
    await expect(field(page, 'operator')).toBeHidden();
    await expect(field(page, 'value1')).toBeHidden();
    // Shift+Tab from the first control goes to the last, Tab from there back to the first: the focus cannot leave.
    await page.keyboard.press('Shift+Tab');
    expect(await focusedField(page)).toBe('ok');
    await page.keyboard.press('Tab');
    expect(await focusedField(page)).toBe('type');
    // Keys typed in the dialog are not keys of the grid.
    await page.keyboard.press('Delete');
    await page.keyboard.press('Escape');
    await expect(dialog(page)).toHaveCount(0);
    expect(await gridHasFocus(page)).toBe(true);
    expect(await ruleAt(page, 'C2')).toBeNull();
    expect(await changes(page)).toBe(0);

    // With the keyboard alone: a whole number between 1 and 5.
    expect(await open(page)).toBe(true);
    await field(page, 'type').selectOption('whole');
    await expect(field(page, 'operator')).toBeVisible();
    await expect(dialog(page).locator('label', { hasText: 'Minimum' })).toBeVisible();
    await expect(dialog(page).locator('label', { hasText: 'Maximum' })).toBeVisible();
    await field(page, 'value1').focus();
    await page.keyboard.type('1');
    await page.keyboard.press('Tab');
    expect(await focusedField(page)).toBe('value2');
    await page.keyboard.type('5');
    await page.keyboard.press('Enter');
    await expect(dialog(page)).toHaveCount(0);
    expect(await gridHasFocus(page)).toBe(true);
    expect(await ruleAt(page, 'C3')).toBe('C2:C4|whole|between|1|5');
    expect(await changes(page)).toBe(1);

    // The rule works at once: 9 is refused with the editor left open, 3 is written.
    await typeIn(page, 'C2', '9');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    expect(await cellValue(page, 'C2')).toBeNull();
    await typeIn(page, 'C2', '3');
    expect(await cellValue(page, 'C2')).toBe(3);
  });

  test('a rule is one undo step, and the dialog shows the rule the cells have', async ({ page }) => {
    await mount(page, await workbook());
    await setRule(page, 'C2:C4', { type: 'decimal', operator: 'greaterThanOrEqual', value1: '2.5', errorTitle: 'Too small', error: 'At least 2.5' });
    expect(await ruleAt(page, 'C4')).toBe('C2:C4|decimal|greaterThanOrEqual|2.5|');
    await typeIn(page, 'C2', '1');
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('Too small: At least 2.5');
    await page.keyboard.press('Escape');

    await page.evaluate(() => (window as any).__editor.view.undo());
    expect(await ruleAt(page, 'C4')).toBeNull();
    await page.evaluate(() => (window as any).__editor.view.redo());
    expect(await ruleAt(page, 'C4')).toBe('C2:C4|decimal|greaterThanOrEqual|2.5|');
    await page.evaluate(() => (window as any).__editor.view.undo());
    // Without the rule the value is written.
    await typeIn(page, 'C2', '1');
    expect(await cellValue(page, 'C2')).toBe(1);
    await page.evaluate(() => (window as any).__editor.view.undo());
    await setRule(page, 'C2:C4', { type: 'decimal', operator: 'greaterThanOrEqual', value1: '2.5', errorTitle: 'Too small', error: 'At least 2.5' });

    // Opened again, the dialog has what the rule says.
    await select(page, 'C3');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'type')).toHaveValue('decimal');
    await expect(field(page, 'operator')).toHaveValue('greaterThanOrEqual');
    await expect(field(page, 'value1')).toHaveValue('2.5');
    await expect(field(page, 'value2')).toBeHidden();
    await expect(field(page, 'errorTitle')).toHaveValue('Too small');
    await expect(field(page, 'error')).toHaveValue('At least 2.5');
    await expect(field(page, 'mixed')).toHaveCount(0);
    // Changed for this one cell: the others keep the rule they had.
    await fill(page, { operator: 'between', value1: '1', value2: '2' });
    await action(page, 'ok').click();
    expect(await ruleAt(page, 'C3')).toBe('C3|decimal|between|1|2');
    expect(await ruleAt(page, 'C2')).toBe('C2 C4|decimal|greaterThanOrEqual|2.5|');
  });

  test('the rule of the file is shown as it would be typed; a selection over several rules says so, and OK replaces them', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'A3');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'type')).toHaveValue('whole');
    await expect(field(page, 'value1')).toHaveValue('1');
    await expect(field(page, 'value2')).toHaveValue('10');
    await expect(field(page, 'errorStyle')).toHaveValue('warning');
    await expect(field(page, 'promptTitle')).toHaveValue('Qty');
    await expect(field(page, 'prompt')).toHaveValue('A whole number');
    await expect(field(page, 'showInputMessage')).toBeChecked();
    await action(page, 'cancel').click();
    await expect(dialog(page)).toHaveCount(0);

    await select(page, 'A2:C3');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'mixed')).toBeVisible();
    // The dialog starts from the rule of the active cell, which only warns: this one is to stop.
    await fill(page, { type: 'textLength', operator: 'lessThan', value1: '4', errorStyle: 'stop' });
    await action(page, 'ok').click();
    expect(await ruleAt(page, 'B2')).toBe('A2:C3|textLength|lessThan|4|');
    expect(await ruleAt(page, 'A4')).toBe('A4:A9|whole|between|1|10');
    expect(await ruleAt(page, 'B4')).toBeNull();
    await typeIn(page, 'B2', 'long text');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'B2', 'abc');
    expect(await cellValue(page, 'B2')).toBe('abc');
  });

  test('a list: its items, or cells of another sheet; the cell offers them, and the arrow can be hidden', async ({ page }) => {
    await mount(page, await workbook());
    await setRule(page, 'C2:C3', { type: 'list', value1: 'Low, Mid, High', promptTitle: 'Level', prompt: 'Pick a level' });
    expect(await ruleAt(page, 'C2')).toBe('C2:C3|list|between|"Low,Mid,High"|');
    await select(page, 'C2');
    // The message of the rule stands beside the cell that is selected.
    await expect(page.locator('#host .bym-tip')).toContainText('Pick a level');
    expect(await page.evaluate(() => (window as any).__editor.view.openValidationList() as boolean)).toBe(true);
    await expect(page.locator('#host .bym-dropdown .bym-list-row')).toHaveText(['Low', 'Mid', 'High']);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C2', 'Other');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C2', 'Mid');
    expect(await cellValue(page, 'C2')).toBe('Mid');

    await setRule(page, 'D2', { type: 'list', value1: '=Lists!$A$1:$A$3', inCellDropdown: false });
    expect(await ruleAt(page, 'D2')).toBe('D2|list|between|Lists!$A$1:$A$3|');
    await select(page, 'D2');
    // No arrow, no list to open; the values are checked all the same.
    expect(await page.evaluate(() => (window as any).__editor.view.openValidationList() as boolean)).toBe(false);
    await typeIn(page, 'D2', 'Purple');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'D2', 'Blue');
    expect(await cellValue(page, 'D2')).toBe('Blue');
  });

  test('dates, times and formulas of their own', async ({ page }) => {
    await mount(page, await workbook());
    await setRule(page, 'C2', { type: 'date', operator: 'greaterThan', value1: '12/31/2024' });
    expect(await ruleAt(page, 'C2')).toBe('C2|date|greaterThan|45657|');
    await typeIn(page, 'C2', '1/1/2024');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C2', '1/1/2025');
    expect(await cellValue(page, 'C2')).toBe(45658);

    await setRule(page, 'C3', { type: 'time', operator: 'between', value1: '9:00', value2: '17:00' });
    expect(await ruleAt(page, 'C3')).toBe('C3|time|between|0.375|0.7083333333333334');
    await typeIn(page, 'C3', '8:00');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C3', '12:00');
    expect(await cellValue(page, 'C3')).toBe(0.5);

    await setRule(page, 'C4:C5', { type: 'custom', value1: '=C4>$A$2' });
    expect(await ruleAt(page, 'C5')).toBe('C4:C5|custom|between|C4>$A$2|');
    await typeIn(page, 'C5', '2');
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
    await typeIn(page, 'C5', '4');
    expect(await cellValue(page, 'C5')).toBe(4);
    // Opened again, the date is a date and the formula is typed with its "=".
    await select(page, 'C2');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'value1')).toHaveValue('12/31/2024');
    await page.keyboard.press('Escape');
    await select(page, 'C4');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'value1')).toHaveValue('=C4>$A$2');
    await page.keyboard.press('Escape');
  });

  test('"any value" with a message keeps the message; "clear all" takes the rules off the selection', async ({ page }) => {
    await mount(page, await workbook());
    await setRule(page, 'C2', { type: 'none', promptTitle: 'Note', prompt: 'Anything goes here' });
    expect(await ruleAt(page, 'C2')).toBe('C2|none|between||');
    await select(page, 'C2');
    await expect(page.locator('#host .bym-tip')).toContainText('Anything goes here');
    // Without a message there is nothing to keep: the cell has no rule.
    await setRule(page, 'C2', { type: 'none', promptTitle: '', prompt: '' });
    expect(await ruleAt(page, 'C2')).toBeNull();

    await select(page, 'A2:B2');
    expect(await open(page)).toBe(true);
    await action(page, 'clear').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleAt(page, 'A2')).toBeNull();
    expect(await ruleAt(page, 'B2')).toBeNull();
    expect(await ruleAt(page, 'A3')).toBe('A3:A9|whole|between|1|10');
    expect(await ruleAt(page, 'B3')).toBe('B3|list|between|"Yes,No"|');
    await typeIn(page, 'A2', '99');
    expect(await cellValue(page, 'A2')).toBe(99);
  });

  test('what cannot be a rule is said in the dialog, which stays open with what was typed', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'C2');
    expect(await open(page)).toBe(true);
    await fill(page, { type: 'whole', operator: 'equal', value1: 'many' });
    await action(page, 'ok').click();
    await expect(alert(page)).toHaveText('Value: enter a whole number or a formula');
    await expect(field(page, 'value1')).toHaveAttribute('aria-invalid', 'true');
    expect(await focusedField(page)).toBe('value1');
    await fill(page, { type: 'custom', value1: '=SUM(A1' });
    await page.keyboard.press('Enter');
    await expect(alert(page)).toHaveText('Formula: the formula cannot be read');
    await fill(page, { type: 'list', value1: 'x,'.repeat(130) });
    await action(page, 'ok').click();
    await expect(alert(page)).toContainText('255');
    await fill(page, { type: 'whole', operator: 'between', value1: '1', value2: '' });
    await action(page, 'ok').click();
    await expect(alert(page)).toHaveText('Maximum is required');
    expect(await focusedField(page)).toBe('value2');
    // Titles and messages cannot be typed longer than Excel takes them; a longer one that is put in is refused.
    await fill(page, { value2: '2' });
    await field(page, 'promptTitle').evaluate((el) => ((el as HTMLInputElement).value = 'x'.repeat(40)));
    await action(page, 'ok').click();
    await expect(alert(page)).toContainText('32');
    await expect(dialog(page)).toBeVisible();
    expect(await ruleAt(page, 'C2')).toBeNull();
    expect(await changes(page)).toBe(0);
    await fill(page, { promptTitle: 'Fine' });
    await action(page, 'ok').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleAt(page, 'C2')).toBe('C2|whole|between|1|2');
  });

  test('saved and opened again, the rules are there; everything undone, the file is the one that was opened', async ({ page }) => {
    const bytes = await workbook();
    await mount(page, bytes);
    await setRule(page, 'C2:C4', { type: 'list', value1: 'a, b', errorStyle: 'information', errorTitle: 'Hm', error: 'Not in the list' });
    // "Any value" for a cell whose rule has an input message keeps the message; cleared, the cell has no rule.
    await select(page, 'A2');
    expect(await open(page)).toBe(true);
    await action(page, 'clear').click();
    const saved = await page.evaluate(async () => {
      const api = (window as any).BymOffice;
      const out = (await (window as any).__file.save()) as Uint8Array;
      const book = await (await api.open(out)).workbook();
      return book.sheets[0].dataValidations.map((rule: any) => `${rule.ranges.map(api.rangeName).join(' ')}|${rule.type}|${rule.formula1 ?? ''}|${rule.errorStyle}|${rule.errorTitle ?? ''}|${rule.error ?? ''}`);
    });
    expect(saved).toEqual(['A3:A9|whole|1|warning|Quantity|Enter 1 to 10', 'B2:B3|list|"Yes,No"|stop||', 'C2:C4|list|"a,b"|information|Hm|Not in the list']);
    await page.evaluate(() => {
      const view = (window as any).__editor.view;
      view.undo();
      view.undo();
    });
    expect(await page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array))).toEqual(Array.from(bytes));
  });

  test('what is being typed is written first; while a formula is typed the dialog does not open', async ({ page }) => {
    await mount(page, await workbook());
    await select(page, 'C2');
    await page.keyboard.type('12');
    expect(await editing(page)).toBe(true);
    expect(await open(page)).toBe(true);
    expect(await editing(page)).toBe(false);
    expect(await cellValue(page, 'C2')).toBe(12);
    await page.keyboard.press('Escape');

    await select(page, 'C3');
    await page.keyboard.type('=1+');
    expect(await open(page)).toBe(false);
    await expect(dialog(page)).toHaveCount(0);
    expect(await editing(page)).toBe(true);
    await expect(message(page)).toHaveText('Finish the formula first');
    await page.keyboard.press('Escape');

    // A value the rule of its cell stops is not written, and then there is no dialog either.
    await page.evaluate(() => (window as any).__editor.view.setValidation((window as any).BymOffice.parseRange('C5'), { type: 'whole', operator: 'equal', formula1: '1' }));
    await select(page, 'C5');
    await page.keyboard.type('7');
    expect(await open(page)).toBe(false);
    expect(await editing(page)).toBe(true);
    await page.keyboard.press('Escape');
  });

  test('a read-only view has no dialog and takes no rule', async ({ page }) => {
    await mount(page, await workbook(), { readOnly: true });
    await select(page, 'C2');
    expect(await open(page)).toBe(false);
    await expect(dialog(page)).toHaveCount(0);
    await page.evaluate(() => (window as any).__editor.view.setValidation((window as any).BymOffice.parseRange('C2'), { type: 'whole', operator: 'equal', formula1: '1' }));
    expect(await ruleAt(page, 'C2')).toBeNull();
    // The rules of the file are still looked up.
    expect(await ruleAt(page, 'A2')).toBe('A2:A9|whole|between|1|10');
  });

  test('in Turkish: labels, ";" between the items of a list and the arguments of a formula, and the decimal comma', async ({ page }) => {
    await mount(page, await workbook(), { locale: 'tr' });
    await select(page, 'C2:C3');
    expect(await open(page)).toBe(true);
    const labelled = await dialog(page).getAttribute('aria-labelledby');
    await expect(page.locator(`#${labelled}`)).toHaveText('Veri doğrulama');
    await expect(field(page, 'type').locator('option')).toHaveText(['Herhangi bir değer', 'Tam sayı', 'Ondalık', 'Liste', 'Tarih', 'Saat', 'Metin uzunluğu', 'Özel formül']);
    await fill(page, { type: 'list', value1: 'evet; hayır' });
    await action(page, 'ok').click();
    expect(await ruleAt(page, 'C2')).toBe('C2:C3|list|between|"evet,hayır"|');

    await setRule(page, 'D2', { type: 'decimal', operator: 'between', value1: '1,5', value2: '=TOPLA($A$2:$A$3; 0,5)' });
    expect(await ruleAt(page, 'D2')).toBe('D2|decimal|between|1.5|SUM($A$2:$A$3, 0.5)');
    await select(page, 'D2');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'value1')).toHaveValue('1,5');
    await expect(field(page, 'value2')).toHaveValue('=SUM($A$2:$A$3; 0,5)');
    // The English way of writing a formula is not taken for another formula.
    await fill(page, { value2: '=SUM(A2,1)' });
    await action(page, 'ok').click();
    await expect(alert(page)).toHaveText('En çok: formül okunamıyor');
    await fill(page, { type: 'date', operator: 'equal', value1: '31.12.2024' });
    await action(page, 'ok').click();
    expect(await ruleAt(page, 'D2')).toBe('D2|date|equal|45657|');
    await select(page, 'C2');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'value1')).toHaveValue('evet; hayır');
    await page.keyboard.press('Escape');
  });

  test('the dialog fits a narrow editor and can be scrolled to every field', async ({ page }) => {
    await page.setViewportSize({ width: 320, height: 480 });
    await mount(page, await workbook());
    await select(page, 'A2');
    expect(await open(page)).toBe(true);
    const host = (await page.locator('#host').boundingBox())!;
    const box = (await dialog(page).boundingBox())!;
    expect(box.x).toBeGreaterThanOrEqual(host.x);
    expect(box.x + box.width).toBeLessThanOrEqual(host.x + host.width + 0.5);
    expect(box.y).toBeGreaterThanOrEqual(host.y);
    expect(box.y + box.height).toBeLessThanOrEqual(host.y + host.height + 0.5);
    // Nothing sticks out sideways, and the last field can be reached.
    expect(await dialog(page).evaluate((el) => el.scrollWidth <= el.clientWidth + 1)).toBe(true);
    await field(page, 'error').scrollIntoViewIfNeeded();
    await field(page, 'error').fill('Not this');
    await action(page, 'ok').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__editor.view.validationAt(1, 0).error)).toBe('Not this');
  });

  test('the cell menu and the toolbar open the dialog', async ({ page, hasTouch }) => {
    await mount(page, await workbook());
    await select(page, 'C2');
    await page.locator('#host [data-command="validation"]').click();
    await expect(dialog(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(dialog(page)).toHaveCount(0);
    // The menu of a cell: C3, at the default sizes of a sheet.
    const canvas = (await page.locator('#host .bym-canvas').boundingBox())!;
    const x = canvas.x + 72 + 64 * 2 + 20;
    const y = canvas.y + 22 + 20 * 2 + 10;
    await page.evaluate(
      ([x, y]) => {
        const event = new MouseEvent('contextmenu', { clientX: x, clientY: y, button: 2, bubbles: true, cancelable: true });
        document.querySelector('#host .bym-canvas')!.dispatchEvent(event);
      },
      [x, y],
    );
    const item = page.locator('#host .bym-menu-item', { hasText: 'Data validation' });
    await expect(item).toBeVisible();
    if (hasTouch) await item.tap();
    else await item.click();
    await expect(dialog(page)).toBeVisible();
    expect(await page.evaluate(() => (window as any).BymOffice.rangeName((window as any).__editor.view.selection.range))).toBe('C3');
    await page.keyboard.press('Escape');
  });

  test('a rule that is opened and closed with OK is not changed: no step, and the file is the one that was opened', async ({ page }) => {
    const bytes = await workbook();
    await mount(page, bytes);
    await select(page, 'B2:B3');
    expect(await open(page)).toBe(true);
    await expect(field(page, 'value1')).toHaveValue('Yes, No');
    await action(page, 'ok').click();
    await expect(dialog(page)).toHaveCount(0);
    expect(await page.evaluate(() => (window as any).__editor.view.history.canUndo)).toBe(false);
    expect(await changes(page)).toBe(0);
    expect(await page.evaluate(async () => Array.from((await (window as any).__file.save()) as Uint8Array))).toEqual(Array.from(bytes));
    // One field changed: the rule stays the element it is, where it is.
    expect(await open(page)).toBe(true);
    await fill(page, { errorTitle: 'Pick' });
    await action(page, 'ok').click();
    expect(
      await page.evaluate(() => (window as any).__editor.view.workbook.sheets[0].dataValidations.map((rule: any) => [rule.src, rule.live === true, rule.formula1, rule.errorTitle ?? null])),
    ).toEqual([[0, false, '1', 'Quantity'], [1, true, '"Yes,No"', 'Pick']]);
    // While the dialog is open, saving applies it; what it cannot take keeps it open.
    await select(page, 'C2');
    expect(await open(page)).toBe(true);
    await fill(page, { type: 'whole', operator: 'equal', value1: 'x' });
    expect(await page.evaluate(() => (window as any).__editor.view.commitPending() as boolean)).toBe(false);
    await expect(dialog(page)).toBeVisible();
    await fill(page, { value1: '4' });
    expect(await page.evaluate(() => (window as any).__editor.view.commitPending() as boolean)).toBe(true);
    await expect(dialog(page)).toHaveCount(0);
    expect(await ruleAt(page, 'C2')).toBe('C2|whole|equal|4|');
  });
});
